n=19; g=[[0]*n for _ in range(n)]
centers={(3,6):8,(4,13):4,(12,14):1,(14,3):2}
for (r,c),v in centers.items(): g[r][c]=v
crosses=[(3,6),(4,13),(12,14),(14,3),(10,8)]
for r,c in crosses:
 for dr,dc in [(-1,0),(1,0),(0,-1),(0,1)]:
  rr,cc=r+dr,c+dc
  g[rr][cc]=3
own={p:{(p[0]+dr,p[1]+dc) for dr,dc in [(-1,0),(1,0),(0,-1),(0,1)]} for p in centers}
# Rays: allow pass through own adjacent 3s; halt on any other 3. Horizontal first, vertical second to match demo overlap precedence.
out=[row[:] for row in g]
for vertical in (False,True):
 for (r,c),v in centers.items():
  dirs=[(-1,0),(1,0)] if vertical else [(0,-1),(0,1)]
  for dr,dc in dirs:
   rr,cc=r+dr,c+dc
   while 0<=rr<n and 0<=cc<n:
    if g[rr][cc]==3 and (rr,cc) not in own[(r,c)]: break
    if g[rr][cc]!=3: out[rr][cc]=v
    rr+=dr;cc+=dc
print('\n'.join(' '.join(map(str,row)) for row in out))

out3=[row[:] for row in out]
# restore colored values on hollow cross row, but keep its center column excluded
for c in range(n):
 if g[10][c]==0: out3[10][c]=0
# Need restore ray values using original pre-mask by recomputing horizontal and vertical rays, with col 8 excluded.
out3=[row[:] for row in g]
for vertical in (False,True):
 for (r,c),v in centers.items():
  for dr,dc in ([(-1,0),(1,0)] if vertical else [(0,-1),(0,1)]):
   rr,cc=r+dr,c+dc
   while 0<=rr<n and 0<=cc<n:
    if g[rr][cc]==3 and (rr,cc) not in own[(r,c)]: break
    if g[rr][cc]!=3 and cc!=8: out3[rr][cc]=v
    rr+=dr;cc+=dc
print('\n'.join(' '.join(map(str,row)) for row in out3))
